// Compara el saldo de ahora con el de la vuelta anterior.
// Los datos estáticos del workflow ($getWorkflowStaticData) se guardan entre ejecuciones cuando el
// workflow corre publicado (por el horario). En las pruebas manuales no se guardan.
const memoria = $getWorkflowStaticData('global');
memoria.saldos = memoria.saldos || {};

const config = $('Wallet a vigilar').first().json;
const direccion = String(config.direccion || '').trim().toLowerCase();
const respuesta = $input.first().json;
if (!/^0x[0-9a-f]{40}$/.test(direccion)) throw new Error('En «Wallet a vigilar», direccion tiene que ser 0x y 40 caracteres hexadecimales.');
if (respuesta.error || typeof respuesta.result !== 'string') throw new Error(`El RPC de Fuji no devolvió el saldo: ${JSON.stringify(respuesta.error ?? respuesta)}`);

function enAVAX(wei) {
  const signo = wei < 0n ? '-' : '';
  const abs = wei < 0n ? -wei : wei;
  const base = 10n ** 18n;
  const resto = (abs % base).toString().padStart(18, '0').replace(/0+$/, '');
  return signo + (resto ? `${abs / base}.${resto}` : `${abs / base}`);
}
function aWei(avax) {
  const t = String(avax).trim().replace(',', '.');
  if (!/^\d+(\.\d{1,18})?$/.test(t)) throw new Error('saldoAnteriorDePrueba tiene que ser un monto en AVAX, por ejemplo "12.5".');
  const [entero, decimales = ''] = t.split('.');
  return BigInt(entero) * 10n ** 18n + BigInt(decimales.padEnd(18, '0'));
}

const actual = BigInt(respuesta.result);
// Para ver el aviso en una prueba manual, completá saldoAnteriorDePrueba: se usa en lugar de la memoria.
const prueba = String(config.saldoAnteriorDePrueba ?? '').trim();
const guardado = memoria.saldos[direccion];
const anterior = prueba ? aWei(prueba) : guardado ? BigInt(guardado.wei) : null;
const diferencia = anterior === null ? 0n : actual - anterior;
const ahora = $now.setZone('America/La_Paz').toFormat('dd/MM/yyyy HH:mm:ss');

// Guardamos el saldo de esta vuelta para compararlo en la próxima.
memoria.saldos[direccion] = { wei: actual.toString(), revisado: ahora };

return [
  {
    json: {
      direccion,
      cambio: anterior !== null && diferencia !== 0n,
      primeraRevision: anterior === null,
      entro: diferencia > 0n,
      saldoAVAX: enAVAX(actual),
      saldoAnteriorAVAX: anterior === null ? null : enAVAX(anterior),
      diferenciaAVAX: enAVAX(diferencia),
      movimientoAVAX: enAVAX(diferencia < 0n ? -diferencia : diferencia),
      revisadoAnterior: prueba ? 'saldo de prueba' : guardado?.revisado ?? null,
      revisado: ahora,
      explorador: `https://build.avax.network/explorer/fuji/c-chain/address/${direccion}`,
    },
  },
];
